// The wholesale lender directory data loads (supabase/migrations/*_int_lender_directory_seed*.sql,
// generated by research_notes/Wholesale lender directory/gen_seed_sql.py). Researched lenders must
// land held for review: inactive and unverified on the panel, with pending-review credit boxes the
// matcher ignores, and nothing written over lenders Corin already works with. Later rounds only add.
import type { PGlite } from "@electric-sql/pglite";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { applyMigrations, createStubbedDb, listMigrations } from "../../../scripts/test-migrations.ts";
import { dealPrograms } from "@/lib/deals/types";
import { assetClasses } from "./types";

const SEED = /_int_lender_directory_seed(?:_round\d+)?\.sql$/;
const ROUND1_ACTOR = "seed:lender-directory-2026-11-02";
const SEEDED = "updated_by like 'seed:lender-directory%'";
const EXISTING = ["vium", "greystone", "cambridge", "lument", "liberty sbf", "harvest", "ready capital", "tmc financing", "roc capital", "fidelis"];

let db: PGlite;
const seeds = listMigrations().filter((f) => SEED.test(f.name));

beforeAll(async () => {
  db = await createStubbedDb();
  await applyMigrations(db, listMigrations());
}, 120_000);

afterAll(async () => {
  await db?.close();
});

const count = async (sql: string) => Number((await db.query<{ n: number }>(sql)).rows[0]!.n);

describe("lender directory seed", () => {
  it("exists and every load runs after the tables it fills", () => {
    expect(seeds.length).toBeGreaterThanOrEqual(1);
    const names = listMigrations().map((f) => f.name);
    const matching = names.findIndex((n) => n.endsWith("_m_lender_matching.sql"));
    for (const s of seeds) expect(names.indexOf(s.name)).toBeGreaterThan(matching);
  });

  it("puts every researched firm on the panel inactive, unverified and with the usury gate still on", async () => {
    const panel = await db.query<{ active: boolean; verified_at: string | null; category: string; fee_split_kind: string; programs: string[]; name: string }>(
      `select active, verified_at, category, fee_split_kind, programs, name from public.lender_panel where ${SEEDED}`,
    );
    expect(panel.rows.length).toBeGreaterThan(150);
    for (const l of panel.rows) {
      expect(l.active).toBe(false);
      expect(l.verified_at).toBeNull();
      expect(l.category).toBe("UNKNOWN");
      expect(l.fee_split_kind).toBe("none");
      for (const p of l.programs) expect(dealPrograms).toContain(p);
    }
    // No firm is added twice, within a load or across loads.
    const names = panel.rows.map((l) => l.name.toLowerCase());
    expect(new Set(names).size).toBe(names.length);
  });

  it("leaves Corin's existing lenders alone", async () => {
    const { rows } = await db.query<{ name: string }>(`select name from public.lender_panel where ${SEEDED}`);
    for (const { name } of rows) for (const e of EXISTING) expect(name.toLowerCase().startsWith(e), name).toBe(false);
  });

  it("adds pending-review boxes, each linked to a seeded lender, that the matcher will not use", async () => {
    const boxes = await db.query<{ status: string; source: string; lender_id: string | null; programs: string[]; asset_classes: string[]; notes: string }>(
      `select status, source, lender_id, programs, asset_classes, notes from public.credit_boxes where ${SEEDED}`,
    );
    expect(boxes.rows.length).toBeGreaterThanOrEqual(await count(`select count(*)::int as n from public.lender_panel where ${SEEDED}`));
    for (const b of boxes.rows) {
      expect(b.status).toBe("pending_review");
      expect(b.source).toBe("staff");
      expect(b.lender_id).not.toBeNull();
      for (const p of b.programs) expect(dealPrograms).toContain(p);
      for (const a of b.asset_classes) expect(assetClasses).toContain(a);
      expect(b.notes.length).toBeLessThanOrEqual(2000);
    }
    expect(await count(`select count(*)::int as n from public.credit_boxes c join public.lender_panel l on l.id = c.lender_id where c.${SEEDED} and not l.${SEEDED}`)).toBe(0);
    expect(await count(`select count(*)::int as n from public.credit_boxes where ${SEEDED} and status = 'approved'`)).toBe(0);
  });

  it("lets a later round add desks to a firm an earlier round loaded, without a second panel row", async () => {
    if (seeds.length < 2) return;
    const linked = await count(
      `select count(*)::int as n from public.credit_boxes c join public.lender_panel l on l.id = c.lender_id
       where c.updated_by <> '${ROUND1_ACTOR}' and c.${SEEDED} and l.updated_by = '${ROUND1_ACTOR}'`,
    );
    expect(linked).toBeGreaterThan(0);
  });

  it("is idempotent", async () => {
    const before = [await count(`select count(*)::int as n from public.lender_panel`), await count(`select count(*)::int as n from public.credit_boxes`)];
    for (const s of seeds) await db.exec(s.sql);
    expect([await count(`select count(*)::int as n from public.lender_panel`), await count(`select count(*)::int as n from public.credit_boxes`)]).toEqual(before);
  });

  it("attaches boxes to a lender staff already added under the same name instead of duplicating it", async () => {
    const fresh = await createStubbedDb();
    try {
      await applyMigrations(fresh, listMigrations().filter((f) => !SEED.test(f.name)));
      const id = (await fresh.query<{ id: string }>(`insert into public.lender_panel (name, category, programs, updated_by) values ('parkview financial', 'CFL_LICENSEE', '{CONSTRUCTION}', 'broker:ana') returning id`)).rows[0]!.id;
      for (const s of seeds) await fresh.exec(s.sql);
      const panel = await fresh.query<{ id: string; category: string; updated_by: string }>(`select id, category, updated_by from public.lender_panel where lower(name) = 'parkview financial'`);
      expect(panel.rows).toEqual([{ id, category: "CFL_LICENSEE", updated_by: "broker:ana" }]);
      const boxes = await fresh.query<{ lender_id: string }>(`select lender_id from public.credit_boxes where ${SEEDED} and label like 'Parkview Financial%'`);
      expect(boxes.rows.length).toBeGreaterThan(0);
      expect(boxes.rows.every((b) => b.lender_id === id)).toBe(true);
    } finally {
      await fresh.close();
    }
  }, 120_000);
});
